            } else if let Ok(op: MultiQubitGateOperation) = MultiQubitGateOperation::try_from(operation) {
                check_acts_on_qubits_in_qureg(operation, qureg)?;
                check_multi_qubit_availability(&op, device)?;
                execute_generic_multi_qubit_operation(operation: &op, qureg)
            } else if let Ok(_op: PragmaNoiseOperation) = PragmaNoiseOperation::try_from(operation) {
