            } else if ALLOWED_OPERATIONS.contains(&operation.hqslang()) {
                Ok(())
            } else {
                Err(RoqoqoBackendError::OperationNotInBackend {
                    backend: "QuEST",
                    hqslang: operation.hqslang(),
                })
            }
        }
    }
}

