            check_single_qubit_availability(op, device)?;
            unsafe {
                quest_sys::rotateX(
                    qureg.quest_qureg,
                    *op.qubit() as c_int,
                    std::f64::consts::FRAC_PI_2,
                )
            }
            Ok(())
        }
        Operation::InvSqrtPauliX(op) => {
            check_acts_on_qubits_in_qureg(operation, qureg)?;
            check_single_qubit_availability(op, device)?;
            unsafe {
                quest_sys::rotateX(
                    qureg.quest_qureg,
                    *op.qubit() as c_int,
                    std::f64::consts::FRAC_PI_2 * -1.0,
                )
            }
            Ok(())
        }
        Operation::SqrtPauliY(op) => {
            check_acts_on_qubits_in_qureg(operation, qureg)?;
            check_single_qubit_availability(op, device)?;
            unsafe {
                quest_sys::rotateY(
                    qureg.quest_qureg,
                    *op.qubit() as c_int,
                    std::f64::consts::FRAC_PI_2,
