    let mut complex_matrix: ComplexMatrixN = ComplexMatrixN::new(number_qubits: 3_u32);
    for ((row: usize, column: usize), value) in unitary_matrix.indexed_iter() {
        complex_matrix.set(row, column, *value).map_err(op: |err: &str| -> RoqoqoBackendError {
            RoqoqoBackendError::GenericError {
