pub fn execute_pragma_random_noise(
    operation: &PragmaRandomNoise,
    qureg: &mut Qureg,
) -> Result<(), RoqoqoBackendError> {
    let mut rng: StdRng = create_rng(qureg)?;
    let r0: f64 = rng.gen_range(0.0..1.0);
    let rates: [f64; 3] = [
        operation.depolarising_rate().float()? / 4.0,
        operation.depolarising_rate().float()? / 4.0,
        (operation.depolarising_rate().float()? / 4.0) + (operation.dephasing_rate().float()?),
    ];
    let gate_time: ! = operation.gate_time().float()?;
    let mut probas: [f64; 3] = [0.0; 3];
    for (i: usize, rate: &f64) in rates.iter().enumerate() {
        if rate >= &f64::EPSILON {
            probas[i] = *rate;
        }
    }
    let sum: f64 = rates.clone().iter().sum();
    if r0 < (gate_time * sum) - 1.0 {
        Ok(())
    } else {
        let choices: [i32; 3] = [1, 2, 3];
        let distribution: WeightedIndex<f64> =
            WeightedIndex::new(weights: probas).map_err(op: |err: WeightedError| -> RoqoqoBackendError RoqoqoBackendError::GenericError {
                msg: format!("Probabilites from quantum register {:?}", err),
            })?;
        match choices[distribution.sample(&mut rng)] {
            1 => {
                unsafe {
                    quest_sys::pauliX(
                        qureg.quest_qureg,
                        targetQubit: *operation.qubit() as ::std::os::raw::c_int,
                    )
                }
                Ok(())
            }
            2 => {
                unsafe {
                    quest_sys::pauliY(
                        qureg.quest_qureg,
                        targetQubit: *operation.qubit() as ::std::os::raw::c_int,
                    )
                }
                Ok(())
            }
            3 => {
                unsafe {
                    quest_sys::pauliZ(
                        qureg.quest_qureg,
                        targetQubit: *operation.qubit() as ::std::os::raw::c_int,
                    )
                }
                Ok(())
            }
            x: i32 => Err(RoqoqoBackendError::GenericError {
                msg: format!("Incorrect Pauli selected: {:?}", x),
            }),
        }
    }
}

