center>
script type="text/tikz">
begin{tikzpicture}[scale=.5]
node[draw=none] at (-3.5, 0) {target};

draw (-2,0) -- (2, 0);
draw (0, 0) circle (.5);
draw (0, .5) -- (0, -.5);
end{tikzpicture}
/script>
/center>
endhtmlonly

@see
- rotateX()
- pauliY()
- pauliZ()
- controlledNot()
- multiQubitNot()
- multiControlledMultiQubitNot()

